import React, { useState } from 'react';
import type { ColDef } from 'ag-grid-community';
import { AllCommunityModule } from 'ag-grid-community';
import { AgGridProvider, AgGridReact } from 'ag-grid-react';

interface IRow {
  barang: string;
  lokasi: string;
  isi: string;
  tapel: string;
  tinggi: string;
  col0: string;
  total: string;
  col6: string;
  omega: string;
  a: string;
  cttn: string;
}

const GridExample = () => {
  const [rowData] = useState<IRow[]>([
    {
      barang: 'Kabel',
      lokasi: 'Gudang A',
      isi: '10',
      tapel: '2024',
      tinggi: '150',
      col0: '0',
      total: '10',
      col6: '6',
      omega: 'Ω1',
      a: 'A',
      cttn: 'Baik',
    },
    {
      barang: 'Pipa',
      lokasi: 'Gudang B',
      isi: '20',
      tapel: '2023',
      tinggi: '200',
      col0: '0',
      total: '20',
      col6: '6',
      omega: 'Ω2',
      a: 'B',
      cttn: 'Rusak',
    },
    {
      barang: 'Baut',
      lokasi: 'Gudang C',
      isi: '100',
      tapel: '2025',
      tinggi: '5',
      col0: '0',
      total: '100',
      col6: '6',
      omega: 'Ω3',
      a: 'C',
      cttn: '-',
    },
  ]);

  const [colDefs] = useState<ColDef<IRow>[]>([
    { field: 'barang', headerName: 'Barang' },
    { field: 'lokasi', headerName: 'Lokasi' },
    { field: 'isi', headerName: 'Isi' },
    { field: 'tapel', headerName: 'Tapel' },
    { field: 'tinggi', headerName: 'Tinggi' },
    { field: 'col0', headerName: '0' },
    { field: 'total', headerName: 'Total' },
    { field: 'col6', headerName: '6' },
    { field: 'omega', headerName: 'Omega' },
    { field: 'a', headerName: 'a' },
    { field: 'cttn', headerName: 'Cttn' },
  ]);

  return (
    <AgGridProvider modules={[AllCommunityModule]}>
      <div className="grid-container">
        <AgGridReact rowData={rowData} columnDefs={colDefs} />
      </div>
    </AgGridProvider>
  );
};

export default GridExample;
